import React, { useEffect, useState } from "react";
import axios from "axios";
import io from "socket.io-client";
import "./Schedule.css";

const socket = io("http://localhost:5000");

const STAGES = ["League", "Qualifier", "Semi Final", "Final"];

const Schedule = () => {
  const user = JSON.parse(localStorage.getItem("user"));
  const isAdmin = user?.role === "Admin";

  const [teams, setTeams] = useState([]);
  const [venue, setVenue] = useState("");
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [matches, setMatches] = useState([]);

  useEffect(() => {
    axios.get("/api/schedule").then(res => setMatches(res.data));
    socket.on("refreshSchedule", () => {
      axios.get("/api/schedule").then(res => setMatches(res.data));
    });
  }, []);

  const generateSchedule = async () => {
    if (!isAdmin) return alert("Admin only");

    let generated = [];
    let currentDate = new Date(startDate);

    STAGES.forEach(stage => {
      for (let i = 0; i < teams.length - 1; i += 2) {
        generated.push({
          teamA: teams[i],
          teamB: teams[i + 1],
          stage,
          venue,
          matchDate: new Date(currentDate),
          timeSlot: "Evening (6–9 PM)"
        });
        currentDate.setDate(currentDate.getDate() + 1);
      }
    });

    await axios.post("/api/schedule/create", { matches: generated });
    socket.emit("scheduleUpdated");
  };

  return (
    <div className="schedule-container">
      <h1>🏆 Tournament Schedule</h1>

      {isAdmin && (
        <div className="card">
          <input placeholder="Venue" onChange={e => setVenue(e.target.value)} />
          <input type="date" onChange={e => setStartDate(e.target.value)} />
          <input type="date" onChange={e => setEndDate(e.target.value)} />
          <button onClick={generateSchedule}>Create Schedule</button>
        </div>
      )}

      <table className="schedule-table">
        <thead>
          <tr>
            <th>Match</th>
            <th>Stage</th>
            <th>Venue</th>
            <th>Date</th>
            <th>Time</th>
          </tr>
        </thead>
        <tbody>
          {matches.map((m, i) => (
            <tr key={i} className={`stage-${m.stage.replace(" ", "").toLowerCase()}`}>
              <td>{m.teamA} vs {m.teamB}</td>
              <td>{m.stage}</td>
              <td>{m.venue}</td>
              <td>{new Date(m.matchDate).toDateString()}</td>
              <td>{m.timeSlot}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default Schedule;
